fn one_off(a: Str, b: Str) -> Bool {
  if a.len() != b.len() {
    return false
  }
  let xs = a.codes()
  let ys = b.codes()
  var diff = 0
  for i in range(0, xs.len()) {
    if xs.get_or(i, 0) != ys.get_or(i, 0) {
      diff = diff + 1
    }
  }
  return diff == 1
}

pub fn ladder(start: Str, goal: Str, words: List[Str]) -> Int {
  if start == goal {
    return 1
  }
  // nodes[0] is the start word; the rest are the words
  let nodes = [start].concat(words)
  let n = nodes.len()
  // dist[v]: number of words in the shortest chain from start to v (-1: not reached)
  var dist: List[Int] = []
  for _u in range(0, n) {
    dist = dist.push(-1)
  }
  dist = dist.set(0, 1)
  var queue: List[Int] = [0]
  var head = 0
  while head < queue.len() {
    let u = queue.get_or(head, 0)
    head = head + 1
    let next_len = dist.get_or(u, 0) + 1
    let word_u = nodes.get_or(u, "")
    for v in range(0, n) {
      if dist.get_or(v, -1) < 0 and one_off(word_u, nodes.get_or(v, "")) {
        dist = dist.set(v, next_len)
        queue = queue.push(v)
      }
    }
  }
  var best = -1
  for v in range(1, n) {
    let d = dist.get_or(v, -1)
    if nodes.get_or(v, "") == goal and d > 0 {
      if best < 0 or d < best {
        best = d
      }
    }
  }
  if best < 0 {
    return 0
  }
  return best
}
